"  
  // Render Tabel B: Sertifikat Live Training & Zoom
  const trainings = JSON.parse(localStorage.getItem("pa_trainings")) || [];
  const attempts = JSON.parse(localStorage.getItem("pa_training_quiz_attempts")) || {};
  const myAttm = attempts[currentUser.email] || {};

  const certRowsTbody = document.getElementById("progress-live-cert-rows");
  if (certRowsTbody) {
    certRowsTbody.innerHTML = "";
    let hasLiveCerts = false;
    trainings.forEach(t => {
      // Hanya tampilkan jika event sudah punya end time ATAU user sudah pernah mencoba kuis (bisa saja event aktif)
      const att = myAttm[t.id];
      const passed = att && att.passed;
      const row = document.createElement("tr");

      let statusHTML = "";
      let aksiHTML = "";
      let scoreText = att ? (att.bestScore || 0) + "%" : "--";

      if (passed) {
        statusHTML = `<span class="status-indicator selesai">Lulus</span>`;
        aksiHTML = `<button class="btn-primary" style="padding:4px 8px; font-size:11px;" onclick="generateTrainingCert('${t.id}')">🖨️ Cetak Sertifikat</button>`;
      } else {
        statusHTML = `<span class="status-indicator belum">Tidak Layak</span>`;
        aksiHTML = `<button class="btn-secondary" style="padding:4px 8px; font-size:11px; opacity:0.5; cursor:not-allowed;" disabled>🖨️ Cetak Sertifikat</button>`;
      }

      row.innerHTML = `
        <td><strong>${t.title}</strong></td>
        <td>${new Date(t.time).toLocaleDateString('id-ID')}</td>
        <td><strong>${scoreText}</strong></td>
        <td>${statusHTML}</td>
        <td>${aksiHTML}</td>
      `;
      certRowsTbody.appendChild(row);
      hasLiveCerts = true;
    });

    if (!hasLiveCerts) {
      certRowsTbody.innerHTML = `<tr><td colspan="5" style="text-align:center; color:var(--text-muted); font-style:italic;">Belum ada riwayat training.</td></tr>`;
    }
  }

  renderTryoutHistoryTable();
}"

